1944:     /// Restrict the scan to physical slices in this dataset snapshot.
1945:     ///
1946:     /// Overlapping slices have set semantics. Deleted rows do not compact offsets.
1947:     /// Empty slices are allowed, but their offsets must still be within the fragment.
1948:     /// Any explicit fragment scope is intersected with these slices, regardless of
1949:     /// setter order. Output follows scan order, not slice order. Replaces an existing
1950:     /// physical selection. V1 storage, ANN and FTS are rejected when planning the scan.
1951:     ///
1952:     /// ```
1953:     /// # use lance::{Dataset, Result};
1954:     /// # use lance::dataset::scanner::FragmentSlice;
1955:     /// # async fn example(dataset: &Dataset, fragment_id: u32) -> Result<()> {
1956:     /// let mut scan = dataset.scan();
1957:     /// scan.with_fragment_slices(&[FragmentSlice {
1958:     ///     fragment_id, row_offset: 0, row_count: 10,
1959:     /// }]).await?;
1960:     /// let batch = scan.try_into_batch().await?;
1961:     /// # Ok(())
1962:     /// # }
1963:     /// ```
1964:     pub async fn with_fragment_slices(&mut self, slices: &[FragmentSlice]) -> Result<&mut Self> {
1965:         let rows = super::fragment_slice::physical_rows_from_slices(&self.dataset, slices).await?;
1966:         Ok(self.with_physical_row_addr_prefilter(rows))
1967:     }
