1969:     /// Restrict the scan to physical row addresses.
1970:     ///
1971:     /// ```
1972:     /// # use lance::{Dataset, Result};
1973:     /// # use lance::dataset::scanner::RowAddrTreeMap;
1974:     /// # async fn example(dataset: &Dataset, rows: RowAddrTreeMap) -> Result<()> {
1975:     /// let mut scan = dataset.scan();
1976:     /// scan.with_physical_row_addr_prefilter(rows);
1977:     /// let batch = scan.try_into_batch().await?;
1978:     /// # Ok(())
1979:     /// # }
1980:     /// ```
1981:     ///
1982:     /// This selection is always keyed by physical `(fragment_id, row_offset)`
1983:     /// addresses, including on datasets that use stable row ids. It is kept in
1984:     /// that domain until scan planning, where it is intersected with fragment
1985:     /// scope, deletion vectors, and any scalar-index result.
1986:     ///
1987:     /// This is independent from [`with_row_id_prefilter`](Self::with_row_id_prefilter),
1988:     /// whose mask is keyed in the dataset's `_rowid` domain. If both are set,
1989:     /// both restrictions apply.
1990:     pub fn with_physical_row_addr_prefilter(&mut self, rows: RowAddrTreeMap) -> &mut Self {
1991:         self.physical_row_addr_prefilter = Some(Arc::new(rows));
1992:         self
