191: /// Bounded random reads from a persistent cache payload. Backends may coalesce
192: /// and align physical I/O while codecs request logical byte ranges.
193: pub trait CacheRangeReader {
194:     fn read_range(&self, range: std::ops::Range<usize>) -> Result<Bytes>;
195: }
196: impl<F: Fn(std::ops::Range<usize>) -> Result<Bytes>> CacheRangeReader for F {
197:     fn read_range(&self, range: std::ops::Range<usize>) -> Result<Bytes> {
198:         self(range)
199:     }
200: }
