202: /// Serialization trait for cache entries.
203: ///
204: /// **Experimental**: the serialized format is not yet covered by a stability
205: /// guarantee and may change between releases. When it does stabilize, the
206: /// rules are: `TYPE_ID`, protobuf field numbers, and enum values are
207: /// append-only forever; format changes that protobuf cannot express
208: /// transparently bump [`CURRENT_VERSION`](Self::CURRENT_VERSION).
209: ///
210: /// Implement this on concrete types that need to survive serialization through
211: /// a persistent cache backend, then wire it into a
212: /// [`CacheKey`](super::CacheKey) via [`CacheCodec::from_impl`].
213: ///
214: /// The envelope (magic/version/type_id/type_version) is written and validated
215: /// by the [`CacheCodec`] wrapper. [`serialize`](Self::serialize) writes only
216: /// the body — a header followed by sections in a fixed, version-keyed order —
217: /// and [`deserialize`](Self::deserialize) reads them back in that same order.
218: /// The read sequence mirroring the write sequence for each `type_version` is
219: /// the invariant the implementor owns.
220: pub trait CacheCodecImpl: Send + Sync {
221:     /// Whether this body supports gathering sorted, unique row offsets.
222:     const SUPPORTS_ROW_SELECTION: bool = false;
223:     fn deserialize_rows(
224:         _reader: &dyn CacheRangeReader,
225:         _body_offset: usize,
226:         _version: u32,
227:         _rows: &[u32],
228:     ) -> Result<Self>
229:     where
230:         Self: Sized,
231:     {
232:         Err(Error::invalid_input(
233:             "cache codec does not support row selection",
234:         ))
235:     }
236: 
237:     /// Payload byte ranges that [`deserialize_rows`](Self::deserialize_rows)
238:     /// requests for `rows`, in request order, excluding the envelope and any
239:     /// body header it reads through `reader` while planning.
240:     ///
241:     /// Lets a backend issue those reads concurrently before decoding. The
242:     /// default `None` means the body cannot plan, and backends read serially.
243:     fn plan_row_ranges(
244:         _reader: &dyn CacheRangeReader,
245:         _body_offset: usize,
246:         _version: u32,
247:         _rows: &[u32],
248:     ) -> Result<Option<Vec<std::ops::Range<usize>>>>
249:     where
250:         Self: Sized,
251:     {
252:         Ok(None)
253:     }
385:     /// Hint for priority-aware memory tiers. Larger values survive pressure first.
386:     pub fn with_memory_priority(mut self, priority: u8) -> Self {
