407:     /// Return the stable entry type identity.
408:     ///
409:     /// Persistent and tiered backends can use this metadata to route encoded
410:     /// values without retaining a readable logical cache key.
411:     pub const fn type_id(&self) -> &'static str {
412:         self.type_id
413:     }
414: 
415:     /// Serialize `value` into `writer`: envelope first, then the body.
416:     pub fn serialize(&self, value: &ArcAny, writer: &mut dyn Write) -> Result<()> {
417:         let body_offset = write_envelope(writer, self.type_id, self.version)?;
418:         let mut entry_writer = CacheEntryWriter::with_pos(writer, body_offset);
419:         (self.serialize_body)(value, &mut entry_writer)
420:     }
421: 
422:     pub fn supports_row_selection(&self) -> bool {
423:         self.row_decoder.is_some()
424:     }
425: 
426:     /// Read and validate the envelope of a range-read entry, returning the
427:     /// body offset and the entry's `type_version`.
428:     fn read_row_envelope(&self, reader: &dyn CacheRangeReader) -> Result<(usize, u32)> {
429:         let prefix = reader.read_range(0..ENVELOPE_ID_OFFSET)?;
430:         let id_bytes = prefix
431:             .get(ENVELOPE_ID_OFFSET - 2..ENVELOPE_ID_OFFSET)
432:             .ok_or_else(|| Error::invalid_input("short cache envelope"))?;
433:         let id_len = u16::from_le_bytes(id_bytes.try_into().unwrap()) as usize;
434:         let header =
435:             reader.read_range(0..(ENVELOPE_ID_OFFSET + id_len + ENVELOPE_VERSION_BYTES))?;
436:         let envelope = parse_envelope(&header)
437:             .ok_or_else(|| Error::invalid_input("invalid cache envelope"))?;
438:         if envelope.type_id != self.type_id || envelope.type_version > self.version {
439:             return Err(Error::invalid_input("incompatible cache entry"));
440:         }
441:         Ok((envelope.body_offset, envelope.type_version))
442:     }
443: 
444:     /// Gather rows without loading the complete persistent entry.
445:     pub fn deserialize_rows(
446:         &self,
447:         reader: &dyn CacheRangeReader,
448:         rows: &[u32],
449:     ) -> CacheDecode<ArcAny> {
450:         let decode = || -> Result<ArcAny> {
451:             let decoder = self
452:                 .row_decoder
453:                 .ok_or_else(|| Error::invalid_input("row selection unsupported"))?;
454:             let (body_offset, version) = self.read_row_envelope(reader)?;
455:             decoder(reader, body_offset, version, rows)
456:         };
457:         match decode() {
458:             Ok(entry) => CacheDecode::Hit(entry),
459:             Err(_) => CacheDecode::Miss(CacheMissReason::BodyError),
460:         }
461:     }
462: 
463:     /// Payload ranges that [`deserialize_rows`](Self::deserialize_rows) would
464:     /// request for `rows`, beyond the envelope and body header it reads from
465:     /// `reader` here. `None` when the codec cannot plan, the entry is not
466:     /// compatible, or the rows are invalid; callers then decode serially,
467:     /// which reports invalid rows as a miss.
468:     pub fn plan_rows(
469:         &self,
470:         reader: &dyn CacheRangeReader,
471:         rows: &[u32],
472:     ) -> Option<Vec<std::ops::Range<usize>>> {
473:         let planner = self.row_planner?;
474:         let (body_offset, version) = self.read_row_envelope(reader).ok()?;
475:         planner(reader, body_offset, version, rows).ok().flatten()

78: /// One concrete codec reused across independently decoded sequence chunks.
79: #[derive(Debug)]
80: pub struct SequenceBlockCodec {
81:     compressor: Box<dyn BlockCompressor>,
82:     expected_encoding: CompressiveEncoding,
83:     has_payload: bool,
84:     estimated_wire_bytes: u64,
85: }
86: 
87: impl SequenceBlockCodec {
88:     pub(crate) fn estimated_wire_bytes(&self) -> u64 {
89:         self.estimated_wire_bytes
90:     }
91: 
92:     pub(crate) fn expected_encoding(&self) -> &CompressiveEncoding {
93:         &self.expected_encoding
94:     }
95: 
96:     pub(crate) fn has_payload(&self) -> bool {
97:         self.has_payload
98:     }
99: 
100:     pub(crate) fn compress(
101:         &self,
102:         data: FixedWidthDataBlock,
103:     ) -> Result<(Option<LanceBuffer>, CompressiveEncoding)> {
104:         let (payload, encoding) = self.compressor.compress(DataBlock::FixedWidth(data))?;
105:         if encoding != self.expected_encoding {
106:             return Err(Error::internal(
107:                 "Sequence block codec produced a different descriptor after selection".to_string(),
108:             ));
109:         }
110:         if payload.is_some() != self.has_payload {
111:             return Err(Error::internal(
112:                 "Sequence block codec changed its payload arity after selection".to_string(),
113:             ));
114:         }
115:         Ok((payload, encoding))
116:     }
117: }
