447:         &self,
448:         offsets: &[N],
449:         data: VariableWidthBlock,
450:         legacy_alignment: usize,
451:         context: MiniBlockCompressionContext,
452:     ) -> Result<(MiniBlockCompressed, CompressiveEncoding)> {
453:         validate_variable_offsets(offsets, data.num_values, data.data.len())?;
454:         let bits_per_offset = data.bits_per_offset as u64;
455:         let legacy_encoding =
456:             ProtobufUtils21::variable(ProtobufUtils21::flat(bits_per_offset, None), None);
457:         let (legacy_buffers, legacy_chunks) =
458:             chunk_offsets(offsets, &data.data, legacy_alignment, self.minichunk_size);
459:         let legacy = MiniBlockCompressed {
460:             data: legacy_buffers,
461:             chunks: legacy_chunks,
462:             num_values: data.num_values,
463:         };
464:         let Some(field_params) = self
465:             .generic_offsets
466:             .as_ref()
467:             .filter(|_| context.allows_generic_offsets())
468:         else {
469:             return Ok((legacy, legacy_encoding));
470:         };
471: 
472:         let ranges = binary_chunk_ranges(offsets, self.minichunk_size);
473:         let member_ranges = ranges
474:             .iter()
475:             .map(|range| range.start_offset_index..range.end_offset_index + 1)
476:             .collect::<Vec<_>>();
477:         let offsets_block = FixedWidthDataBlock {
478:             bits_per_value: bits_per_offset,
479:             data: data.offsets.clone(),
480:             num_values: offsets.len() as u64,
481:             block_info: BlockInfo::default(),
482:         };
483:         let extra_payload_header = context
484:             .chunk_header_bytes(2)
485:             .saturating_sub(context.chunk_header_bytes(1));
486:         let codec = select_block_codec(
487:             &offsets_block,
488:             &member_ranges,
489:             field_params,
490:             BlockCost::new(extra_payload_header, 8),
491:             true,
492:         )?;
493:         if matches!(
494:             codec.expected_encoding().compression.as_ref(),
495:             Some(Compression::Flat(_))
496:         ) {
497:             return Ok((legacy, legacy_encoding));
498:         }
499: 
500:         let (generic, generic_encoding) = build_generic_chunks(&data, offsets, &ranges, &codec)?;
501:         if serialized_variable_cost(&generic, &generic_encoding, context)
502:             < serialized_variable_cost(&legacy, &legacy_encoding, context)
503:         {
504:             Ok((generic, generic_encoding))
505:         } else {
506:             Ok((legacy, legacy_encoding))
