594: fn decode_generic_binary_miniblock(
595:     bits_per_offset: u8,
596:     offsets: &dyn BlockDecompressor,
597:     offsets_have_payload: bool,
598:     data: Vec<LanceBuffer>,
599:     num_values: u64,
600: ) -> Result<DataBlock> {
601:     let expected_buffers = 1 + usize::from(offsets_have_payload);
602:     if data.len() != expected_buffers {
603:         return Err(Error::corrupt_file_named(
604:             "binary mini-block",
605:             format!(
606:                 "generic chunk has {} buffers, expected {expected_buffers}",
607:                 data.len()
608:             ),
609:         ));
610:     }
611:     let mut buffers = data.into_iter();
612:     let offset_payload =
613:         offsets_have_payload.then(|| buffers.next().expect("buffer count was checked"));
614:     let values = buffers.next().expect("buffer count was checked");
615:     let num_offsets = num_values.checked_add(1).ok_or_else(|| {
616:         Error::corrupt_file_named(
617:             "binary mini-block",
618:             format!("cannot decode offsets for {num_values} values"),
619:         )
620:     })?;
621:     let decoded = offsets.decompress(offset_payload, num_offsets)?;
622:     let DataBlock::FixedWidth(offsets) = decoded else {
623:         return Err(Error::corrupt_file_named(
624:             "binary mini-block",
625:             "generic offset codec did not produce fixed-width offsets",
626:         ));
627:     };
628:     if offsets.bits_per_value != u64::from(bits_per_offset) || offsets.num_values != num_offsets {
629:         return Err(Error::corrupt_file_named(
630:             "binary mini-block",
631:             format!(
632:                 "generic offset codec produced {} {}-bit offsets, expected {num_offsets} {bits_per_offset}-bit offsets",
633:                 offsets.num_values, offsets.bits_per_value
634:             ),
635:         ));
636:     }
637: 
638:     match bits_per_offset {
639:         32 => {
640:             let typed = checked_fixed_values::<u32>(&offsets, "Binary mini-block offsets")?;
641:             let mut previous = 0_u32;
642:             for (position, &offset) in typed.iter().enumerate() {
643:                 if (position == 0 && offset != 0) || offset < previous || offset > i32::MAX as u32 {
644:                     return Err(Error::corrupt_file_named(
645:                         "binary mini-block",
646:                         format!("invalid 32-bit generic offset {offset} at position {position}"),
647:                     ));
648:                 }
649:                 previous = offset;
650:             }
651:             if previous as usize != values.len() {
652:                 return Err(Error::corrupt_file_named(
653:                     "binary mini-block",
654:                     format!(
655:                         "final generic offset {previous} does not equal the {}-byte value buffer",
656:                         values.len()
657:                     ),
658:                 ));
659:             }
660:         }
661:         64 => {
662:             let typed = checked_fixed_values::<u64>(&offsets, "Binary mini-block offsets")?;
663:             let mut previous = 0_u64;
664:             for (position, &offset) in typed.iter().enumerate() {
665:                 if (position == 0 && offset != 0) || offset < previous || offset > i64::MAX as u64 {
666:                     return Err(Error::corrupt_file_named(
667:                         "binary mini-block",
668:                         format!("invalid 64-bit generic offset {offset} at position {position}"),
669:                     ));
670:                 }
671:                 previous = offset;
672:             }
673:             let value_len = u64::try_from(values.len()).map_err(|_| {
674:                 Error::corrupt_file_named(
675:                     "binary mini-block",
676:                     "value buffer length does not fit u64",
677:                 )
678:             })?;
679:             if previous != value_len {
680:                 return Err(Error::corrupt_file_named(
681:                     "binary mini-block",
682:                     format!(
683:                         "final generic offset {previous} does not equal the {}-byte value buffer",
684:                         values.len()
685:                     ),
686:                 ));
687:             }
688:         }
689:         _ => unreachable!("generic offset width was validated during decoder construction"),
690:     }
691: 
692:     Ok(DataBlock::VariableWidth(VariableWidthBlock {
693:         data: values,
694:         offsets: offsets.data,
695:         bits_per_offset,
696:         num_values,
697:         block_info: BlockInfo::new(),
698:     }))

