74:         }
75:         // Preserve the original budget exactly, including legacy rounding and
76:         // clipping behavior, when the new option is omitted or set to default.
77:         if query.search_effort == 0.5 {
78:             return;
79:         }
80:         let upper = distances
81:             .len()
82:             .min(query.maximum_nprobes.unwrap_or(distances.len()));
83:         if upper == 0 {
84:             query.minimum_nprobes = 0;
85:             return;
86:         }
87:         let lower = caller_minimum.max(1).min(upper);
88:         let auto = query.minimum_nprobes.clamp(lower, upper);
89:         let effort = query.search_effort;
90:         // Round-off near 0.5 can move the geometric budget past Auto. Bound
91:         // each half separately so increasing effort preserves the midpoint.
92:         query.minimum_nprobes = if effort == 0.0 {
93:             lower
94:         } else if effort == 1.0 {
95:             upper
96:         } else if effort < 0.5 {
97:             let budget = lower as f64 * (auto as f64 / lower as f64).powf(2.0 * effort);
98:             (budget.ceil() as usize).clamp(lower, auto)
99:         } else {
100:             let budget = auto as f64 * (upper as f64 / auto as f64).powf(2.0 * effort - 1.0);
101:             (budget.ceil() as usize).clamp(auto, upper)
102:         };
103:     }
189:         let bucket = match query.k {
190:             ..=1 => 0,
191:             2..=10 => 1,
192:             11..=100 => 2,
193:             101..=200 => 3,
194:             201..=500 => 4,
195:             501..=1000 => 5,
196:             1001..=10_000 => 6,
197:             _ => 7,
198:         };
199:         // Profiles depend only on metric and k; every index uses the same values.
200:         // Larger-k buckets are calibrated at their upper endpoints on separate
201:         // queries from the native evaluation (benchmarks/auto-ivf-large-k).
202:         // Each bucket uses its measured upper-endpoint profile; measurements do
203:         // not establish recall guarantees for every intermediate k. The policy
204:         // gate retains legacy probing above the largest calibrated endpoint.
205:         let (default_margin, default_minimum, cap) = match metric {
206:             DistanceType::L2 => (
207:                 [0.2175, 0.265, 0.33, 0.375, 0.3725, 0.4175, 0.57, 0.75][bucket],
208:                 [5, 6, 11, 15, 22, 29, 98, 463][bucket],
209:                 [19, 24, 38, 56, 81, 93, 238, 704][bucket],
210:             ),
211:             DistanceType::Cosine => (
212:                 [0.235, 0.2875, 0.38, 0.415, 0.45, 0.47, 0.6475, 0.58][bucket],
213:                 [3, 8, 7, 18, 28, 34, 104, 738][bucket],
214:                 [50, 77, 106, 156, 192, 248, 447, 958][bucket],
215:             ),
216:             // Calibrated on unnormalized Wiki-Cohere and DPR vectors. An initial
217:             // cap controls overscanning without limiting later filtered search.
218:             DistanceType::Dot => (
219:                 [0.14, 0.055, 0.0625, 0.0675, 0.07, 0.0725, 0.0825, 0.21][bucket],
220:                 [56, 144, 200, 211, 244, 279, 517, 1009][bucket],
221:                 [112, 432, 768, 833, 971, 1092, 1824, 2528][bucket],
222:             ),
223:             _ => return Ok(Some(Self::default())),
224:         };

