593: impl MemIndexSpec {
594:     /// One index over one column, maintained by `plugin` with no parameters.
595:     pub fn for_plugin(
596:         name: impl Into<String>,
597:         field_id: i32,
598:         column: impl Into<String>,
599:         plugin: Arc<dyn MemIndexPlugin>,
600:     ) -> Self {
601:         Self::single_column(name, field_id, column, plugin, Arc::new(()))
602:     }
603: 
604:     /// One index over one column, with the parameters its plugin builds from.
605:     pub fn single_column(
606:         name: impl Into<String>,
607:         field_id: i32,
608:         column: impl Into<String>,
609:         plugin: Arc<dyn MemIndexPlugin>,
610:         params: Arc<dyn MemIndexParams>,
611:     ) -> Self {
612:         Self {
613:             name: name.into(),
614:             field_ids: vec![field_id],
615:             columns: vec![column.into()],
616:             plugin,
617:             params,
618:             index_details: None,
619:         }
620:     }
621: 
622:     /// Whether `other` describes the same index: name, columns, field ids,
623:     /// plugin type, plugin version, settings and base-table index details.
624:     pub fn same_index(&self, other: &Self) -> bool {
625:         self.name == other.name
626:             && self.columns == other.columns
627:             && self.field_ids == other.field_ids
628:             && (self.plugin.as_ref() as &dyn Any).type_id()
629:                 == (other.plugin.as_ref() as &dyn Any).type_id()
630:             && self.plugin.details_message() == other.plugin.details_message()
631:             && self.plugin.version() == other.plugin.version()
632:             && self.params.same_as(other.params.as_ref())
633:             && self.index_details == other.index_details
634:     }
635: 
636:     /// `params` as `P`, the type its plugin's own
637:     /// [`resolve`](MemIndexPlugin::resolve) returned.
638:     pub fn params<P: Any>(&self) -> Result<&P> {
639:         downcast_params(&self.name, self.params.as_ref())
640:     }
641: 
642:     /// The context this spec's plugin validates and builds against.
643:     fn build_context<'a>(
644:         &'a self,
645:         schema: &'a LanceSchema,
646:         capacity_rows: usize,
647:         capacity_batches: usize,
648:     ) -> MemIndexBuildContext<'a> {
649:         MemIndexBuildContext {
650:             name: &self.name,
651:             schema,
652:             field_ids: &self.field_ids,
653:             columns: &self.columns,
654:             capacity_rows,
655:             capacity_batches,
656:             params: self.params.as_ref(),
657:         }
658:     }
659: 
660:     /// Check that this spec's plugin can maintain it against `schema`.
661:     pub fn validate(&self, schema: &LanceSchema) -> Result<()> {
662:         check_column_count(&self.name, &self.columns, &self.field_ids)?;
663:         self.plugin.validate(&self.build_context(schema, 0, 0))?;
664:         if self.plugin.flush_index_type().is_scalar() {
665:             self.plugin.flush_params(self)?;
666:         }
667:         Ok(())
668:     }
669: 
670:     /// Build the index this spec describes.
671:     pub fn build(
672:         &self,
673:         schema: &LanceSchema,
674:         capacity_rows: usize,
675:         capacity_batches: usize,
676:     ) -> Result<Arc<dyn MemIndex>> {
677:         check_column_count(&self.name, &self.columns, &self.field_ids)?;
678:         self.plugin
679:             .create(&self.build_context(schema, capacity_rows, capacity_batches))
680:     }
681: }
682: 
683: /// Columns and field ids are parallel lists; a plugin indexes them pairwise.
684: fn check_column_count(name: &str, columns: &[String], field_ids: &[i32]) -> Result<()> {
685:     if columns.len() != field_ids.len() {
686:         return Err(Error::invalid_input(format!(
687:             "index '{name}' names {} columns but {} field ids",
688:             columns.len(),
689:             field_ids.len()
690:         )));
691:     }
692:     Ok(())
693: }
694: 
695: impl std::fmt::Debug for MemIndexSpec {
696:     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
697:         f.debug_struct("MemIndexSpec")
698:             .field("name", &self.name)
699:             .field("columns", &self.columns)
700:             .field("field_ids", &self.field_ids)
701:             .field("plugin", &self.plugin.name())
702:             .field("version", &self.plugin.version())
703:             .field("params", &self.params)
704:             .finish()
705:     }
706: }

6: //! JSONB encoding for Lance JSON columns.
7: //!
8: //! Lance stores `lance.json` columns as JSONB values in `LargeBinary` arrays.
9: //! This crate owns that encoding: it parses JSON text into JSONB
10: //! ([`parse_value`], [`OwnedJsonb`]), reads JSONB values ([`RawJsonb`],
11: //! [`from_raw_jsonb`]), and evaluates SQL/JSONPath expressions over them
12: //! ([`jsonpath`]).
13: //!
14: //! ```
15: //! use lance_jsonb::OwnedJsonb;
16: //! use lance_jsonb::jsonpath::{Selector, parse_json_path};
17: //!
18: //! let jsonb: OwnedJsonb = r#"{"user":{"name":"Ada","tags":["a","b"]}}"#.parse().unwrap();
19: //! let path = parse_json_path(b"$.user.tags[1]").unwrap();
20: //! let value = Selector::new(jsonb.as_raw()).select_value(&path).unwrap().unwrap();
21: //! assert_eq!(value.to_string(), r#""b""#);
22: //! ```
23: //!
24: //! The implementation is adapted from
25: //! [databendlabs/jsonb](https://github.com/databendlabs/jsonb) and keeps only
26: //! what Lance uses. See the crate README for the upstream revision and the
27: //! differences from it.
28: //!
29: //! ## Compatibility
30: //!
31: //! The byte layout below is persisted in Lance data files. Every change must
32: //! keep reading values written by released Lance versions, and writers must keep
33: //! producing bytes that those versions can read. `tests/it/compat.rs` pins the
34: //! bytes produced for representative inputs.
35: //!
36: //! ## Encoding format
37: //!
38: //! The JSONB encoding format is a tree-like structure. Each node contains a container header, a number of JEntry headers, and nested encoding values.
39: //!
40: //! - 32-bit container header. 3 bits identify the type of value, including `scalar`, `object` and `array`, and 29 bits identify the number of JEntries in the `array` or `object`. The root node of the `jsonb` value is always a container header.
41: //!   - `scalar` container header: `0x20000000`
42: //!   - `object` container header: `0x40000000`
43: //!   - `array` container header: `0x80000000`
44: //! - 32-bit JEntry header. 1 bit identifies whether the JEntry stores a length or an offset, 3 bits identify the type of value, including `null`, `string`, `number`, `false`, `true` and `container`, and the remaining 28 bits identify the length or offset of the encoding value.
45: //!   - `null` JEntry header: `0x00000000`
46: //!   - `string` JEntry header: `0x10000000`
47: //!   - `number` JEntry header: `0x20000000`
48: //!   - `false` JEntry header: `0x30000000`
49: //!   - `true` JEntry header: `0x40000000`
50: //!   - `container` JEntry header `0x50000000`
51: //! - Encoding value. Different types of JEntry header have different encoding values.
52: //!   - `null`, `true`, `false`: no encoding value, identified by the JEntry header.
53: //!   - `string`: a normal UTF-8 string.
54: //!   - `number`: an encoded number to represent uint64s, int64s and float64s.
55: //!   - `container`: a nested `json` value with a recursive structure.
56: //!
57: //! #### An encoding example
58: //!
59: //! ```text
60: //! // JSON value
61: //! [false, 10, {"k":"v"}]
62: //!
63: //! // JSONB encoding
64: //! 0x80000003    array container header (3 JEntries)
65: //! 0x30000000    false JEntry header (no encoding value)
66: //! 0x20000002    number JEntry header (encoding value length 2)
67: //! 0x5000000e    container JEntry header (encoding value length 14)
68: //! 0x500a        number encoding value (10)
69: //! 0x40000001    object container header (1 JEntry)
70: //! 0x10000001    string key JEntry header (encoding value length 1)
71: //! 0x10000001    string value JEntry header (encoding value length 1)
72: //! 0x6b          string encoding value ("k")
73: //! 0x76          string encoding value ("v")
74: //! ```
75: 
