1375: pub(crate) fn infer_fixed_width_block_bits(description: &CompressiveEncoding) -> Result<u64> {
1376:     fn infer(description: &CompressiveEncoding, depth: u8) -> Result<u64> {
1377:         if depth > 2 {
1378:             return Err(Error::invalid_input(
1379:                 "Generic block encoding exceeds the supported nesting depth",
1380:             ));
1381:         }
1382:         let compression = description.compression.as_ref().ok_or_else(|| {
1383:             Error::invalid_input("Block encoding is missing its compression variant")
1384:         })?;
1385:         match compression {
1386:             Compression::Flat(flat) => Ok(flat.bits_per_value),
1387:             Compression::Constant(constant) => constant
1388:                 .value
1389:                 .as_ref()
1390:                 .map(|value| value.len() as u64 * 8)
1391:                 .ok_or_else(|| Error::invalid_input("Typed Constant is missing its scalar value")),
1392:             Compression::Range(range) => Ok(range.uncompressed_bits_per_value),
1393:             Compression::Delta(delta) => Ok(delta.uncompressed_bits_per_value),
1394:             Compression::InlineBitpacking(bitpacking) => Ok(bitpacking.uncompressed_bits_per_value),
1395:             Compression::OutOfLineBitpacking(bitpacking) => {
1396:                 Ok(bitpacking.uncompressed_bits_per_value)
1397:             }
1398:             Compression::General(general) => infer(
1399:                 general.values.as_deref().ok_or_else(|| {
1400:                     Error::invalid_input("General block compression is missing its values encoding")
1401:                 })?,
1402:                 depth + 1,
1403:             ),
1404:             Compression::Rle(rle) => infer(
1405:                 rle.values.as_deref().ok_or_else(|| {
1406:                     Error::invalid_input("RLE compression is missing its values encoding")
1407:                 })?,
1408:                 depth + 1,
1409:             ),
1410:             Compression::Dictionary(dictionary) => infer(
1411:                 dictionary.items.as_deref().ok_or_else(|| {
1412:                     Error::invalid_input("Dictionary is missing its items encoding")
1413:                 })?,
1414:                 depth + 1,
1415:             ),
1416:             other => Err(Error::invalid_input(format!(
1417:                 "Cannot infer fixed-width output from {}",
1418:                 compression_name(other)
1419:             ))),
1420:         }
1421:     }
1422: 
1423:     let bits = infer(description, 0)?;
1424:     if !matches!(bits, 32 | 64) {
1425:         return Err(Error::invalid_input(format!(
1426:             "Generic block offsets require 32 or 64-bit values, got {bits}"
1427:         )));
1428:     }
1429:     Ok(bits)
1430: }
