1432: /// Builds the bounded decoder tree used by generic unsigned block sequences.
1433: ///
1434: /// This is intentionally separate from [`DecompressionStrategy::create_block_decompressor`]:
1435: /// stable 2.1/2.2 block readers keep their existing grammar and framing, while
1436: /// the 2.3 offset and sparse containers opt into this typed grammar explicitly.
1437: pub(crate) fn create_fixed_width_block_decompressor(
1438:     description: &CompressiveEncoding,
1439:     expected_bits_per_value: u64,
1440: ) -> Result<Box<dyn BlockDecompressor>> {
1441:     if !matches!(expected_bits_per_value, 32 | 64) {
1442:         return Err(Error::invalid_input(format!(
1443:             "Generic block decoding only supports 32 or 64-bit values, got {expected_bits_per_value}"
1444:         )));
1445:     }
1446:     create_fixed_width_block_decompressor_inner(description, expected_bits_per_value, true)
1447: }
1448: 
1449: /// Validates a generic unsigned block descriptor with its container-owned cardinality.
1450: ///
1451: /// This grammar is for unstable 2.3 containers. Empty sequences require a Constant
1452: /// with no scalar. Payload framing and decoded values are checked when the block is read.
1453: pub fn validate_fixed_width_block_sequence(
1454:     description: &CompressiveEncoding,
1455:     bits_per_value: u64,
1456:     num_values: u64,
1457: ) -> Result<()> {
1458:     crate::encodings::physical::sequence::SequenceDecoder::try_new(
1459:         description,
1460:         bits_per_value,
1461:         num_values,
1462:     )
1463:     .map(|_| ())
1464: }
1465: 
1466: fn create_fixed_width_block_decompressor_inner(
1467:     description: &CompressiveEncoding,
1468:     expected_bits_per_value: u64,
1469:     allow_composite: bool,
1470: ) -> Result<Box<dyn BlockDecompressor>> {
1471:     let compression = description
1472:         .compression
1473:         .as_ref()
1474:         .ok_or_else(|| Error::invalid_input("Block encoding is missing its compression variant"))?;
1475:     match compression {
1476:         Compression::Flat(flat) => {
1477:             if flat.bits_per_value != expected_bits_per_value {
1478:                 return Err(Error::invalid_input(format!(
1479:                     "Flat declares {}-bit values, expected {expected_bits_per_value}",
1480:                     flat.bits_per_value
1481:                 )));
1482:             }
1483:             if flat.data.is_some() {
1484:                 return Err(Error::invalid_input(
1485:                     "Generic block Flat cannot contain buffer compression",
1486:                 ));
1487:             }
1488:             Ok(Box::new(ValueDecompressor::from_flat(flat)))
1489:         }
1490:         Compression::Constant(constant) => {
1491:             let value = constant
1492:                 .value
1493:                 .as_ref()
1494:                 .map(|_| decode_fixed_width_constant(constant, expected_bits_per_value))
1495:                 .transpose()?;
1496:             Ok(Box::new(ConstantBlockDecompressor::new(
1497:                 expected_bits_per_value,
1498:                 value,
1499:             )))
1500:         }
1501:         Compression::Range(range) => {
1502:             if range.uncompressed_bits_per_value != expected_bits_per_value {
1503:                 return Err(Error::invalid_input(format!(
1504:                     "Range declares {}-bit values, expected {expected_bits_per_value}",
1505:                     range.uncompressed_bits_per_value
1506:                 )));
1507:             }
1508:             Ok(Box::new(RangeDecompressor::new(
1509:                 expected_bits_per_value,
1510:                 range.start,
1511:                 range.step,
1512:             )))
1513:         }
1514:         Compression::InlineBitpacking(bitpacking) => {
1515:             if bitpacking.uncompressed_bits_per_value != expected_bits_per_value {
1516:                 return Err(Error::invalid_input(format!(
1517:                     "Inline bitpacking declares {}-bit values, expected {expected_bits_per_value}",
1518:                     bitpacking.uncompressed_bits_per_value
1519:                 )));
1520:             }
1521:             if bitpacking.values.is_some() {
1522:                 return Err(Error::invalid_input(
1523:                     "Generic Inline bitpacking cannot contain buffer compression",
1524:                 ));
1525:             }
1526:             #[cfg(feature = "bitpacking")]
1527:             {
1528:                 Ok(Box::new(InlineBitpacking::from_description(bitpacking)))
1529:             }
1530:             #[cfg(not(feature = "bitpacking"))]
1531:             {
1532:                 Err(Error::not_supported_source(
1533:                     "this runtime was not built with bitpacking support".into(),
1534:                 ))
1535:             }
1536:         }
1537:         Compression::OutOfLineBitpacking(bitpacking) => {
1538:             if bitpacking.uncompressed_bits_per_value != expected_bits_per_value {
1539:                 return Err(Error::invalid_input(format!(
1540:                     "Out-of-line bitpacking declares {}-bit values, expected {expected_bits_per_value}",
1541:                     bitpacking.uncompressed_bits_per_value
1542:                 )));
1543:             }
1544:             let values = bitpacking.values.as_deref().ok_or_else(|| {
1545:                 Error::invalid_input("Out-of-line bitpacking is missing its values encoding")
1546:             })?;
1547:             let compressed_bits = match values.compression.as_ref() {
1548:                 Some(Compression::Flat(flat)) if flat.data.is_none() => flat.bits_per_value,
1549:                 _ => {
1550:                     return Err(Error::invalid_input(
1551:                         "Out-of-line bitpacking values must use plain Flat encoding",
1552:                     ));
1553:                 }
1554:             };
1555:             if compressed_bits == 0 || compressed_bits >= expected_bits_per_value {
1556:                 return Err(Error::invalid_input(format!(
1557:                     "Out-of-line bitpacking width {compressed_bits} is invalid for {expected_bits_per_value}-bit values"
1558:                 )));
1559:             }
1560:             #[cfg(feature = "bitpacking")]
1561:             {
1562:                 Ok(Box::new(OutOfLineBitpacking::new(
1563:                     compressed_bits,
1564:                     expected_bits_per_value,
1565:                 )))
1566:             }
1567:             #[cfg(not(feature = "bitpacking"))]
1568:             {
1569:                 Err(Error::not_supported_source(
1570:                     "this runtime was not built with bitpacking support".into(),
1571:                 ))
1572:             }
1573:         }
1574:         Compression::Delta(delta) if allow_composite => {
1575:             if delta.uncompressed_bits_per_value != expected_bits_per_value {
1576:                 return Err(Error::invalid_input(format!(
1577:                     "Delta declares {}-bit values, expected {expected_bits_per_value}",
1578:                     delta.uncompressed_bits_per_value
1579:                 )));
1580:             }
1581:             let child = delta.deltas.as_deref().ok_or_else(|| {
1582:                 Error::invalid_input("Delta is missing its deltas child encoding")
1583:             })?;
1584:             let child =
1585:                 create_fixed_width_block_decompressor_inner(child, expected_bits_per_value, false)?;
1586:             Ok(Box::new(DeltaDecompressor::new(
1587:                 expected_bits_per_value,
1588:                 delta.base,
1589:                 child,
1590:             )))
1591:         }
1592:         Compression::General(general) if allow_composite => {
1593:             let child = general.values.as_deref().ok_or_else(|| {
1594:                 Error::invalid_input("General block compression is missing its values encoding")
1595:             })?;
1596:             if !matches!(
1597:                 child.compression.as_ref(),
1598:                 Some(Compression::Flat(flat))
1599:                     if flat.bits_per_value == expected_bits_per_value && flat.data.is_none()
1600:             ) {
1601:                 return Err(Error::invalid_input(
1602:                     "Generic General compression must wrap plain Flat values",
1603:                 ));
1604:             }
1605:             let child =
1606:                 create_fixed_width_block_decompressor_inner(child, expected_bits_per_value, false)?;
1607:             let compression = general.compression.as_ref().ok_or_else(|| {
1608:                 Error::invalid_input("General block compression is missing its compression config")
1609:             })?;
1610:             let scheme = compression.scheme().try_into()?;
1611:             let config = CompressionConfig::new(scheme, compression.level);
1612:             Ok(Box::new(FixedWidthGeneralBlockDecompressor::new(
1613:                 child,
1614:                 config,
1615:                 expected_bits_per_value,
1616:             )))
1617:         }
1618:         Compression::Rle(rle) if allow_composite => {
1619:             let values = rle.values.as_deref().ok_or_else(|| {
1620:                 Error::invalid_input("RLE compression is missing its values encoding")
1621:             })?;
1622:             let run_lengths = rle.run_lengths.as_deref().ok_or_else(|| {
1623:                 Error::invalid_input("RLE compression is missing its run-length encoding")
1624:             })?;
1625:             let run_count = match run_lengths.compression.as_ref() {
1626:                 Some(Compression::Constant(constant)) => {
1627:                     BlockRleRunCount::ConstantRunLength(decode_fixed_width_constant(constant, 32)?)
1628:                 }
1629:                 Some(Compression::Range(range)) if range.uncompressed_bits_per_value == 32 => {
1630:                     BlockRleRunCount::RangeRunLengths {
1631:                         start: range.start,
1632:                         step: range.step,
1633:                     }
1634:                 }
1635:                 _ if matches!(values.compression.as_ref(), Some(Compression::Flat(flat)) if flat.bits_per_value == expected_bits_per_value && flat.data.is_none()) => {
1636:                     BlockRleRunCount::FlatValues
1637:                 }
1638:                 _ if matches!(run_lengths.compression.as_ref(), Some(Compression::Flat(flat)) if flat.bits_per_value == 32 && flat.data.is_none()) => {
1639:                     BlockRleRunCount::FlatRunLengths
1640:                 }
1641:                 _ => {
1642:                     return Err(Error::invalid_input(
1643:                         "RLE requires metadata run lengths or one plain Flat child to recover the run count",
1644:                     ));
1645:                 }
1646:             };
1647:             let values = create_fixed_width_block_decompressor_inner(
1648:                 values,
1649:                 expected_bits_per_value,
1650:                 false,
1651:             )?;
1652:             let run_lengths = create_fixed_width_block_decompressor_inner(run_lengths, 32, false)?;
1653:             Ok(Box::new(BlockRleDecompressor::try_new(
1654:                 expected_bits_per_value,
1655:                 values,
1656:                 run_lengths,
1657:                 run_count,
1658:             )?))
1659:         }
1660:         Compression::Dictionary(dictionary) if allow_composite => {
1661:             let indices = dictionary.indices.as_deref().ok_or_else(|| {
1662:                 Error::invalid_input("Dictionary is missing its indices encoding")
1663:             })?;
1664:             let items = dictionary
1665:                 .items
1666:                 .as_deref()
1667:                 .ok_or_else(|| Error::invalid_input("Dictionary is missing its items encoding"))?;
1668:             let indices = create_fixed_width_block_decompressor_inner(indices, 32, false)?;
1669:             let items =
1670:                 create_fixed_width_block_decompressor_inner(items, expected_bits_per_value, false)?;
1671:             Ok(Box::new(BlockDictionaryDecompressor::try_new(
1672:                 expected_bits_per_value,
1673:                 dictionary.num_dictionary_items,
1674:                 indices,
1675:                 items,
1676:             )?))
1677:         }
1678:         other => Err(Error::invalid_input(format!(
1679:             "{} is not allowed at this position in a generic block encoding",
1680:             compression_name(other)
1681:         ))),
1682:     }
1683: }
