1685: fn decode_fixed_width_constant(
1686:     constant: &crate::format::pb21::Constant,
1687:     bits_per_value: u64,
1688: ) -> Result<u64> {
1689:     let value = constant
1690:         .value
1691:         .as_ref()
1692:         .ok_or_else(|| Error::invalid_input("Typed Constant is missing its scalar value"))?;
1693:     let expected_bytes = usize::try_from(bits_per_value / 8)
1694:         .map_err(|_| Error::invalid_input("Constant scalar width does not fit usize"))?;
1695:     if value.len() != expected_bytes {
1696:         return Err(Error::invalid_input(format!(
1697:             "Constant scalar has {} bytes, expected {expected_bytes}",
1698:             value.len()
1699:         )));
1700:     }
1701:     Ok(match bits_per_value {
1702:         32 => u64::from(u32::from_le_bytes(
1703:             value
1704:                 .as_ref()
1705:                 .try_into()
1706:                 .expect("constant width was checked"),
1707:         )),
1708:         64 => u64::from_le_bytes(
1709:             value
1710:                 .as_ref()
1711:                 .try_into()
1712:                 .expect("constant width was checked"),
1713:         ),
1714:         _ => {
1715:             return Err(Error::invalid_input(format!(
1716:                 "Constant only supports 32 or 64-bit values, got {bits_per_value}"
1717:             )));
1718:         }
1719:     })
1720: }
