1722: pub(crate) fn validate_delta_child_encoding(
1723:     child: &CompressiveEncoding,
1724:     expected_bits_per_value: u64,
1725: ) -> Result<()> {
1726:     let child_bits_per_value = match child.compression.as_ref() {
1727:         Some(Compression::Flat(flat)) => flat.bits_per_value,
1728:         Some(Compression::Constant(constant)) => {
1729:             decode_fixed_width_constant(constant, expected_bits_per_value)?;
1730:             expected_bits_per_value
1731:         }
1732:         Some(Compression::Range(range)) => range.uncompressed_bits_per_value,
1733:         Some(Compression::InlineBitpacking(bitpacking)) => bitpacking.uncompressed_bits_per_value,
1734:         Some(Compression::OutOfLineBitpacking(bitpacking)) => {
1735:             bitpacking.uncompressed_bits_per_value
1736:         }
1737:         Some(other) => {
1738:             return Err(Error::invalid_input(format!(
1739:                 "Delta does not support a {} child",
1740:                 compression_name(other)
1741:             )));
1742:         }
1743:         None => {
1744:             return Err(Error::invalid_input(
1745:                 "Delta child is missing its compression variant",
1746:             ));
1747:         }
1748:     };
1749:     if child_bits_per_value != expected_bits_per_value {
1750:         return Err(Error::invalid_input(format!(
1751:             "Delta child declares {child_bits_per_value}-bit values, expected {expected_bits_per_value}"
1752:         )));
1753:     }
1754:     Ok(())

33: impl SequenceDecoder {
34:     pub(crate) fn try_new(
35:         encoding: &CompressiveEncoding,
36:         bits: u64,
37:         num_values: u64,
38:     ) -> Result<Self> {
39:         if matches!(encoding.compression.as_ref(), Some(Compression::Constant(c)) if c.value.is_none())
40:         {
41:             if num_values != 0 {
42:                 return Err(Error::invalid_input(
43:                     "An absent unsigned Constant scalar requires zero values",
44:                 ));
45:             }
46:         } else if num_values == 0 {
47:             return Err(Error::invalid_input(
48:                 "An empty unsigned sequence requires Constant with no scalar",
49:             ));
50:         }
51:         let decoder = create_fixed_width_block_decompressor(encoding, bits)?;
52:         let metadata = metadata(encoding, bits, num_values)?;
53:         Ok(Self {
54:             decoder: Arc::from(decoder),
55:             num_values,
56:             metadata,
57:         })
58:     }
59: 
60:     pub(crate) fn metadata(&self) -> Option<SequenceMetadata> {
61:         self.metadata
62:     }
63: 
64:     pub(crate) fn requires_payload(&self) -> bool {
65:         self.decoder.requires_payload()
66:     }
67: 
68:     pub(crate) fn decode(&self, payload: Option<LanceBuffer>) -> Result<DataBlock> {
69:         self.decoder.decompress(payload, self.num_values)
70:     }
71: }
