73: // The typed decoder has already validated scalar widths and bounded child grammar.
74: fn metadata(
75:     encoding: &CompressiveEncoding,
76:     bits: u64,
77:     count: u64,
78: ) -> Result<Option<SequenceMetadata>> {
79:     Ok(match encoding.compression.as_ref() {
80:         Some(Compression::Constant(c)) => {
81:             let Some(scalar) = c.value.as_ref() else {
82:                 return Ok(Some(SequenceMetadata::Empty));
83:             };
84:             let mut bytes = [0; 8];
85:             bytes[..scalar.len()].copy_from_slice(scalar);
86:             Some(SequenceMetadata::Constant(u64::from_le_bytes(bytes)))
87:         }
88:         Some(Compression::Range(r)) => {
89:             checked_range_last(bits, r.start, r.step, count)?;
90:             Some(SequenceMetadata::Range {
91:                 start: r.start,
92:                 step: r.step,
93:             })
94:         }
95:         Some(Compression::Delta(d)) => {
96:             if count < 2 || (bits == 32 && d.base > u32::MAX as u64) {
97:                 return Err(Error::invalid_input("Invalid Delta cardinality or base"));
98:             }
99:             let child = d
100:                 .deltas
101:                 .as_deref()
102:                 .ok_or_else(|| Error::invalid_input("Missing Delta child"))?;
103:             match metadata(child, bits, count - 1)? {
104:                 Some(SequenceMetadata::Constant(0)) => Some(SequenceMetadata::Constant(d.base)),
105:                 Some(SequenceMetadata::Constant(step)) => {
106:                     checked_range_last(bits, d.base, step, count)?;
107:                     Some(SequenceMetadata::Range {
108:                         start: d.base,
109:                         step,
110:                     })
111:                 }
112:                 _ => None,
113:             }
114:         }
115:         _ => None,
116:     })
117: }

477: /// Validate newly referenced field IDs before advancing the high-water mark.
478: ///
479: /// A data-only operation must not manufacture allocator state by putting an
480: /// otherwise unknown ID in a data-file or overlay mapping. IDs above the parent
481: /// high-water mark are legal only when the canonical successor schema contains
482: /// that newly allocated identity. Overwrite has no retained physical state, so
483: /// every non-negative reference must belong to its replacement schema.
484: pub fn validate_non_reusable_field_id_transition(
485:     parent: &Manifest,
486:     successor: &Manifest,
487:     operation: &Operation,
488: ) -> Result<()> {
489:     let Some(parent_max_field_id) = parent.max_allocated_field_id else {
490:         return Ok(());
491:     };
492:     let Some(successor_max_field_id) = successor.max_allocated_field_id else {
493:         return Err(Error::invalid_input(
494:             "Non-reusable field-ID activation marker is missing from the successor manifest",
495:         ));
496:     };
497:     if successor_max_field_id < parent_max_field_id {
498:         return Err(Error::invalid_input(format!(
499:             "Non-reusable field-ID high-water mark decreases from {parent_max_field_id} to {successor_max_field_id}"
500:         )));
501:     }
502:     let successor_schema_ids = successor
503:         .schema
504:         .fields_pre_order()
505:         .map(|field| field.id)
506:         .collect::<HashSet<_>>();
507: 
508:     if !matches!(operation, Operation::Restore { .. }) {
509:         validate_new_field_ids(
510:             parent,
511:             successor.schema.fields_pre_order().filter(|field| {
512:                 matches!(operation, Operation::Overwrite { .. })
513:                     || parent.schema.field_by_id(field.id).is_none()
514:             }),
515:         )?;
516:     }
517: 
518:     for field_id in successor
519:         .fragments
520:         .iter()
521:         .flat_map(|fragment| fragment.referenced_lance_files())
522:         .flat_map(|file| file.fields.iter())
523:         .copied()
524:         .filter(|field_id| *field_id >= 0)
525:     {
526:         if matches!(operation, Operation::Overwrite { .. })
527:             && !successor_schema_ids.contains(&field_id)
528:         {
529:             return Err(Error::invalid_input(format!(
530:                 "Overwrite references field ID {field_id}, which is not in its replacement schema"
531:             )));
532:         }
533:         if field_id > parent_max_field_id && !successor_schema_ids.contains(&field_id) {
534:             return Err(Error::invalid_input(format!(
535:                 "Data file or overlay references new field ID {field_id}, but the canonical successor schema does not contain that identity"
536:             )));
537:         }
538:     }
539:     Ok(())
540: }
