542: fn validate_new_field_ids<'a>(
543:     manifest: &Manifest,
544:     new_fields: impl Iterator<Item = &'a Field>,
545: ) -> Result<()> {
546:     let max_allocated_field_id = manifest.max_field_id();
547:     for field in new_fields {
548:         if field.id <= max_allocated_field_id {
549:             return Err(Error::invalid_input(format!(
550:                 "New field '{}' has ID {}, but non-reusable field IDs must be greater than the high-water mark {}",
551:                 field.name, field.id, max_allocated_field_id
552:             )));
553:         }
554:     }
555:     Ok(())
556: }
557: 
558: fn validate_non_reusable_field_id_operation(
559:     manifest: &Manifest,
560:     operation: &Operation,
561: ) -> Result<()> {
562:     if !manifest.uses_non_reusable_field_ids() {
563:         return Ok(());
564:     }
565:     validate_non_reusable_field_id_manifest(manifest)?;
566: 
567:     let (Operation::Overwrite { schema, .. }
568:     | Operation::Merge { schema, .. }
569:     | Operation::Project { schema, .. }) = operation
570:     else {
571:         return Ok(());
572:     };
573:     schema.validate()?;
574: 
575:     if matches!(operation, Operation::Overwrite { .. }) {
576:         return validate_new_field_ids(manifest, schema.fields_pre_order());
577:     }
578: 
579:     for field in schema.fields_pre_order() {
580:         let Some(prior_field) = manifest.schema.field_by_id(field.id) else {
581:             continue;
582:         };
583:         if field.parent_id != prior_field.parent_id {
584:             return Err(Error::invalid_input(format!(
585:                 "Field ID {} moves from parent {} to parent {}; non-reusable field identity cannot move between parents",
586:                 field.id, prior_field.parent_id, field.parent_id
587:             )));
588:         }
589:         if field.logical_type != prior_field.logical_type {
590:             return Err(Error::invalid_input(format!(
591:                 "Field ID {} changes logical type from {} to {}; type replacement must allocate a new field ID",
592:                 field.id, prior_field.logical_type, field.logical_type
593:             )));
594:         }
595:     }
596: 
597:     validate_new_field_ids(
598:         manifest,
599:         schema
600:             .fields_pre_order()
601:             .filter(|field| manifest.schema.field_by_id(field.id).is_none()),
602:     )
603: }
