605: /// Reject detached schema changes once non-reusable field identity is active.
606: pub fn validate_detached_non_reusable_field_ids(
607:     manifest: &Manifest,
608:     operation: &Operation,
609: ) -> Result<()> {
610:     if !manifest.uses_non_reusable_field_ids() {
611:         return Ok(());
612:     }
613:     match operation {
614:         Operation::Merge { schema, .. } if schema == &manifest.schema => Ok(()),
615:         Operation::Merge { .. }
616:         | Operation::Project { .. }
617:         | Operation::Overwrite { .. }
618:         | Operation::Restore { .. } => Err(Error::invalid_input(
619:             "Detached commits cannot change schema after non-reusable field IDs are activated",
620:         )),
621:         _ => Ok(()),
622:     }
623: }
826: ///
827: /// Readers resolve columns by field id (name -> schema id -> DataFile::fields
828: /// position), so renumbered ids silently rebind live columns to other columns'
829: /// bytes. Shared ids may be renamed to unused names within the same parent,
830: /// but must not take another sibling's name or move between parents. Parent ids
831: /// must agree with the actual schema tree. Their logical type, nullability,
832: /// storage encoding, and dictionary may change only when every
833: /// existing base or overlay file carrying the id is replaced and every
834: /// proposed fragment materializes the id in a base data file. New ids must
835: /// exceed the manifest's max so a dropped field's id is never reused. An
836: /// existing path may move to a fresh id only when every proposed fragment
837: /// materializes that id in a base data file (the `alter_columns` cast path).
838: /// Omitting a field (dropping it) and updating field metadata remain legal.
839: fn merge_schema_valid(
840:     manifest: &Manifest,
841:     new_schema: &Schema,
842:     fragments: &[Fragment],
843: ) -> Result<()> {
844:     let prior_schema = &manifest.schema;
845:     // First occurrence wins: a later staged fragment with placeholder id 0 is
846:     // not fragment 0's merged version.
847:     let mut new_fragment_map: HashMap<u64, &Fragment> = HashMap::new();
848:     for fragment in fragments {
849:         new_fragment_map.entry(fragment.id).or_insert(fragment);
850:     }
851: 
852:     // Remap and semantic errors first: a renumbered schema usually violates
853:     // both the shared-id and new-id clauses.
854:     for field in new_schema.fields_pre_order() {
855:         let Some(prior_field) = prior_schema.field_by_id(field.id) else {
856:             continue;
857:         };
858:         // A cloned field can keep a stale parent_id after moving in the schema tree.
859:         let prior_parent = prior_schema
860:             .field_ancestry_by_id(field.id)
861:             .ok_or_else(|| {
862:                 Error::internal(format!(
863:                     "Missing prior schema ancestry for field id {}",
864:                     field.id
865:                 ))
866:             })?
867:             .into_iter()
868:             .rev()
869:             .nth(1);
870:         let new_parent = new_schema
871:             .field_ancestry_by_id(field.id)
872:             .ok_or_else(|| {
873:                 Error::internal(format!(
874:                     "Missing proposed schema ancestry for field id {}",
875:                     field.id
876:                 ))
877:             })?
878:             .into_iter()
879:             .rev()
880:             .nth(1);
881:         let prior_parent_id = prior_parent.map_or(-1, |parent| parent.id);
882:         let new_parent_id = new_parent.map_or(-1, |parent| parent.id);
883:         if prior_field.parent_id != prior_parent_id || field.parent_id != new_parent_id {
884:             return Err(Error::invalid_input(format!(
885:                 "Merge operation has inconsistent parent ids for field id {} (\"{}\"): \
886:                  prior field declares {} but its schema ancestry has {}; proposed field \
887:                  declares {} but its schema ancestry has {}.",
888:                 field.id,
889:                 new_schema.field_path(field.id)?,
890:                 prior_field.parent_id,
891:                 prior_parent_id,
892:                 field.parent_id,
893:                 new_parent_id
894:             )));
895:         }
896:         // Match siblings by parent id so an ancestor rename does not hide renumbering.
897:         let prior_siblings = prior_parent.map_or(prior_schema.fields.as_slice(), |parent| {
898:             parent.children.as_slice()
899:         });
900:         if new_parent_id != prior_parent_id
901:             || prior_siblings
902:                 .iter()
903:                 .any(|sibling| sibling.name == field.name && sibling.id != field.id)
904:         {
905:             return Err(Error::invalid_input(format!(
906:                 "Merge operation remaps field id {} from \"{}\" to \"{}\". \
907:                  Merge must preserve the dataset's field ids: derive the new schema \
908:                  from the dataset's current schema instead of renumbering fields.",
909:                 field.id,
910:                 prior_schema.field_path(field.id)?,
911:                 new_schema.field_path(field.id)?
912:             )));
913:         }
914:         if let Some(changes) = shared_field_binding_changes(prior_field, field)
915:             && !is_field_binding_fully_rewritten(manifest, &new_fragment_map, field.id)
916:         {
917:             return Err(Error::invalid_input(format!(
918:                 "Merge operation changes field id {} (\"{}\") without rewriting it in \
919:                  every existing fragment: {}. Merge must preserve each existing field's \
920:                  logical type, nullability, storage encoding, and dictionary unless all \
921:                  existing base and overlay files carrying that field are replaced.",
922:                 field.id,
923:                 new_schema.field_path(field.id)?,
924:                 changes
925:             )));
926:         }
927:     }
928: 
929:     let max_field_id = manifest.max_field_id();
930:     for field in new_schema.fields_pre_order() {
931:         if prior_schema.field_by_id(field.id).is_none() && field.id <= max_field_id {
932:             let next_id_msg = match max_field_id.checked_add(1) {
933:                 Some(next_id) => format!("New fields must use ids of at least {}.", next_id),
934:                 None => {
935:                     "No further field id can be allocated because ids are exhausted.".to_string()
936:                 }
937:             };
938:             return Err(Error::invalid_input(format!(
939:                 "Merge operation assigns id {} to new field \"{}\", but ids up to {} are \
940:                  already used by current or dropped fields. {}",
941:                 field.id,
942:                 new_schema.field_path(field.id)?,
943:                 max_field_id,
944:                 next_id_msg
945:             )));
946:         }
947:     }
948: 
949:     let mut prior_paths = HashMap::with_capacity(prior_schema.fields_pre_order().count());
950:     for field in prior_schema.fields_pre_order() {
951:         prior_paths.insert(prior_schema.field_path(field.id)?, field);
952:     }
953:     for field in new_schema.fields_pre_order() {
954:         if prior_schema.field_by_id(field.id).is_some() {
955:             continue;
956:         }
957:         let new_path = new_schema.field_path(field.id)?;
958:         let Some(prior_field) = prior_paths.get(&new_path) else {
959:             continue;
960:         };
961:         let materialized = fragments.iter().all(|fragment| {
962:             fragment
963:                 .files
964:                 .iter()
965:                 .any(|file| file_materializes_field(file.fields.as_ref(), field))
966:         });
967:         if !materialized {
968:             return Err(Error::invalid_input(format!(
969:                 "Merge operation remaps existing field \"{}\" from id {} to id {} without \
970:                  rewriting its data. Every proposed fragment must materialize the new field \
971:                  id in a base data file.",
972:                 new_path, prior_field.id, field.id
973:             )));
974:         }
975:     }
976: 
977:     Ok(())
978: }
979: 
980: fn file_materializes_field(file_field_ids: &[i32], field: &Field) -> bool {
981:     file_field_ids.contains(&field.id)
982:         || field
983:             .children
984:             .iter()
985:             .any(|child| file_materializes_field(file_field_ids, child))
986: }

157:     fn admit_priority(
158:         &self,
159:         key: InternalCacheKey,
160:         item: QuickEntry,
161:         priority: u8,
162:         generation: u64,
163:     ) {
164:         self.cache.remove(&key);
165:         let dropped = {
166:             let mut entries = self.priority.lock().unwrap_or_else(|e| e.into_inner());
167:             if self.generation.load(Ordering::Acquire) != generation {
168:                 return;
169:             }
170:             let mut dropped = Vec::new();
171:             if !self.priority_active.swap(true, Ordering::AcqRel) {
172:                 // Metadata and existing entries compete with signs, ahead of ex planes.
173:                 // Reserving the whole budget for planes would otherwise evict the IVF model.
174:                 let existing: Vec<_> = self.cache.iter().collect();
175:                 for (key, value) in existing {
176:                     let size = key_footprint(&key).saturating_add(value.size_bytes);
177:                     dropped.extend(entries.insert(key, value, size, 3, self.capacity));
178:                 }
179:                 // Evict resident values without invalidating single-flight
180:                 // placeholders: their loaders still belong to this generation.
181:                 self.cache.set_capacity(0);
182:             }
183:             let size = key_footprint(&key).saturating_add(item.size_bytes);
184:             dropped.extend(entries.insert(
185:                 key,
186:                 item,
187:                 size,
188:                 if priority == 0 { 3 } else { priority },
189:                 self.capacity,
190:             ));
191:             dropped
192:         };
193:         drop(dropped);
194:     }
244:         key: &InternalCacheKey,
245:         entry: CacheEntry,
246:         size_bytes: usize,
247:         codec: Option<CacheCodec>,
248:     ) {
249:         let priority = codec.map(|c| c.memory_priority()).unwrap_or(0);
250:         let item = QuickEntry { entry, size_bytes };
251:         if priority > 0 || self.priority_active.load(Ordering::Acquire) {
252:             self.admit_priority(
253:                 *key,
254:                 item,
255:                 priority,
256:                 self.generation.load(Ordering::Acquire),
257:             );
258:         } else {
259:             self.cache.insert(*key, item);
260:         }
261:     }
262: 
263:     async fn get_or_insert<'a>(
264:         &self,
265:         key: &InternalCacheKey,
266:         loader: Pin<Box<dyn Future<Output = Result<(CacheEntry, usize)>> + Send + 'a>>,
267:         codec: Option<CacheCodec>,
268:     ) -> Result<(CacheEntry, bool)> {
269:         let priority = codec.map(|c| c.memory_priority()).unwrap_or(0);
270:         if (priority > 0 || self.priority_active.load(Ordering::Acquire))
271:             && let Some(value) = self
272:                 .priority
273:                 .lock()
274:                 .unwrap_or_else(|e| e.into_inner())
275:                 .get(key)
276:         {
277:             return Ok((value.entry, true));
278:         }
279:         let generation = self.generation.load(Ordering::Acquire);
280:         match self.cache.get_value_or_guard_async(key).await {
281:             Ok(value) => Ok((value.entry, true)),
282:             Err(guard) => {
283:                 let (entry, size_bytes) = loader.await?;
284:                 let item = QuickEntry {
285:                     entry: entry.clone(),
286:                     size_bytes,
287:                 };
288:                 if guard.insert(item.clone()).is_ok()
289:                     && (priority > 0 || self.priority_active.load(Ordering::Acquire))
290:                 {
291:                     self.admit_priority(*key, item, priority, generation);
292:                 }
293:                 Ok((entry, false))
294:             }
295:         }
296:     }
297: 
298:     async fn clear(&self) {
299:         self.generation.fetch_add(1, Ordering::AcqRel);
300:         let dropped = {
301:             let mut entries = self.priority.lock().unwrap_or_else(|e| e.into_inner());
302:             let dropped = entries.clear();
303:             self.priority_active.store(false, Ordering::Release);
304:             self.cache.set_capacity(self.capacity as u64);
305:             dropped
306:         };
307:         drop(dropped);

27: impl<T: Clone> PriorityEntries<T> {
28:     pub fn is_empty(&self) -> bool {
29:         self.entries.is_empty()
30:     }
31: 
32:     pub fn len(&self) -> usize {
33:         self.entries.len()
34:     }
35:     pub fn bytes(&self) -> usize {
36:         self.bytes as usize
37:     }
38:     pub fn get(&mut self, key: &InternalCacheKey) -> Option<T> {
39:         let (priority, stamp, _, value) = self.entries.get_mut(key)?;
40:         self.order.remove(&(*priority, *stamp));
41:         self.sequence += 1;
42:         *stamp = self.sequence;
43:         self.order.insert((*priority, *stamp), *key);
44:         Some(value.clone())
45:     }
46:     /// Look up an entry without refreshing its recency.
47:     pub fn peek(&self, key: &InternalCacheKey) -> Option<&T> {
48:         self.entries.get(key).map(|(_, _, _, value)| value)
49:     }
50: 
51:     /// Membership only; unlike [`get`](Self::get), recency is unchanged.
52:     pub fn contains(&self, key: &InternalCacheKey) -> bool {
53:         self.entries.contains_key(key)
54:     }
55:     pub fn remove(&mut self, key: &InternalCacheKey) -> Option<T> {
56:         let (priority, stamp, bytes, value) = self.entries.remove(key)?;
57:         self.order.remove(&(priority, stamp));
58:         self.bytes -= bytes as u128;
59:         Some(value)
60:     }
61:     pub fn insert(
62:         &mut self,
63:         key: InternalCacheKey,
64:         value: T,
65:         bytes: usize,
66:         priority: u8,
67:         capacity: usize,
68:     ) -> Vec<T> {
69:         let mut dropped = Vec::new();
70:         if let Some(old) = self.remove(&key) {
71:             dropped.push(old);
72:         }
73:         if bytes > capacity {
74:             dropped.push(value);
75:             return dropped;
76:         }
77:         self.sequence += 1;
78:         self.entries
79:             .insert(key, (priority, self.sequence, bytes, value));
80:         self.order.insert((priority, self.sequence), key);
81:         self.bytes += bytes as u128;
82:         while self.bytes > capacity as u128 {
83:             if let Some(key) = self.order.first_key_value().map(|(_, key)| *key)
84:                 && let Some(value) = self.remove(&key)
85:             {
86:                 dropped.push(value);
87:             }
88:         }
89:         dropped
90:     }
91:     pub fn clear(&mut self) -> Vec<T> {
92:         self.order.clear();
93:         self.bytes = 0;
94:         self.entries
95:             .drain()
96:             .map(|(_, (_, _, _, value))| value)
97:             .collect()
98:     }

3300:     /// Activate monotonic, non-reusable field IDs for a legacy dataset.
3301:     ///
3302:     /// The activation commit records the current maximum referenced field ID as
3303:     /// a persistent high-water mark. Later schema changes allocate above it even
3304:     /// after fields and their files are dropped. Activation is one-way and
3305:     /// idempotent.
3306:     ///
3307:     /// Before calling this method, ensure that all clients that can write to the
3308:     /// dataset enforce writer feature flags, rejecting writes when they do not
3309:     /// support a required flag. Clients that ignore these flags must no longer
3310:     /// write to the dataset: they may discard the high-water mark and allow
3311:     /// field IDs to be reused. This method cannot enforce that client policy.
3312:     ///
3313:     /// ```
3314:     /// # use lance::{Dataset, Result};
3315:     /// # async fn activate(dataset: &mut Dataset) -> Result<()> {
3316:     /// dataset.migrate_to_non_reusable_field_ids().await?;
3317:     /// # Ok(())
3318:     /// # }
3319:     /// ```
3320:     pub async fn migrate_to_non_reusable_field_ids(&mut self) -> Result<()> {
3321:         if self.manifest.uses_non_reusable_field_ids() {
3322:             return Ok(());
3323:         }
3324: 
3325:         let mut repaired_manifest = self.manifest.as_ref().clone();
3326:         fix_schema(&mut repaired_manifest)?;
3327:         let transaction = Transaction::new(
3328:             self.manifest.version,
3329:             Operation::Merge {
3330:                 fragments: repaired_manifest.fragments.as_ref().clone(),
3331:                 schema: repaired_manifest.schema,
3332:                 preserves_nullability: true,
3333:             },
3334:             None,
3335:         );
3336:         let new_ds = CommitBuilder::new(Arc::new(self.clone()))
3337:             .with_max_retries(0)
3338:             .with_non_reusable_field_id_migration_activation()
3339:             .execute(transaction)
3340:             .await?;
3341:         *self = new_ds;
3342:         Ok(())
3343:     }

190:         manifest.max_fragment_id = manifest
191:             .max_fragment_id
192:             .max(current_manifest.max_fragment_id);
193:         if current_manifest.uses_non_reusable_field_ids() {
194:             // Before activation, different fields could share an ID across versions.
195:             // Keeping today's high-water mark cannot prevent restoring such a collision.
196:             let Some(restored_max_field_id) = manifest.max_allocated_field_id else {
197:                 return Err(Error::invalid_input(format!(
198:                     "Cannot restore version {version}: non-reusable field IDs were activated after that version"
199:                 )));
200:             };
201:             manifest.max_allocated_field_id =
202:                 Some(restored_max_field_id.max(current_manifest.max_field_id()));
203:             manifest.writer_feature_flags |= FLAG_NON_REUSABLE_FIELD_IDS;
204:         }

168: message SparseLayout {
169:   // Description of the compression of values.
170:   CompressiveEncoding value_compression = 1;
171:   /* Structural layers ordered from outer-most to inner-most. This may be empty for a flat,
172:    * non-nullable leaf page. The terminal domain gives the leaf slot count, including nulls.
173:    */
174:   repeated SparseStructuralLayer structural_layers = 2;
175: }
176: 
177: /* A domain is a layer-local integer coordinate space [0, size). A slot is one
178:  * element in that space. The outer-most domain is the page's top-level rows; each
179:  * layer's child domain is the next layer's parent domain, and the terminal child
180:  * domain contains the leaf value slots. Parent sizes are derived from the page row count
181:  * and preceding layers, not stored in each layer. The outer size is the page row count
182:  * divided exactly by the product of all fixed-size-list dimensions, including those below lists.
183:  */
184: message SparseStructuralLayer {
185:   // Exactly one layer kind is required.
186:   oneof layer {
187:     SparseValiditySet validity = 1;
188:     SparseListLayer list = 2;
189:     SparseFixedSizeListLayer fixed_size_list = 3;
190:   }
191: }
192: 
193: message SparseListLayer {
194:   // Child-domain size, equal to the sum of counts; available before reading count payloads.
195:   uint64 num_child_slots = 1;
196:   // Non-empty parent slots. Valid parent slots absent from this set are empty lists.
197:   CompressiveEncoding non_empty_positions = 2;
198:   // Cardinality of both non_empty_positions and counts.
199:   uint64 num_non_empty_positions = 3;
200:   // Positive child counts corresponding one-for-one with non_empty_positions.
201:   CompressiveEncoding counts = 4;
202:   // Validity for the parent slots in this layer.
203:   SparseValiditySet validity = 5;
204: }
205: 
206: message SparseFixedSizeListLayer {
207:   // Positive number of children per parent slot. The child-domain size is parent size * dimension.
208:   uint64 dimension = 1;
209:   // Validity for the parent slots in this layer.
210:   SparseValiditySet validity = 2;
211: }
212: 
213: message SparseValiditySet {
214:   enum Meaning {
215:     SPARSE_VALIDITY_UNSPECIFIED = 0;
216:     // Stored positions are null; all other positions are valid.
217:     SPARSE_VALIDITY_NULL_POSITIONS = 1;
218:     // Stored positions are valid; all other positions are null.
219:     SPARSE_VALIDITY_VALID_POSITIONS = 2;
220:   }
221: 
222:   Meaning meaning = 1;
223:   /* Required unsigned u64 block encoding of strictly increasing absolute positions.
224:    * The cardinality is num_positions. All values must be below the owning domain's
225:    * derived size. This descriptor is required even when the sequence is empty.
226:    *
227:    * Positions and list counts follow the generic unsigned block contract,
228:    * including empty sequences and payload framing. Counts need not be increasing.
229:    */
230:   CompressiveEncoding positions = 2;
231:   // Semantic cardinality of the stored positions.
232:   uint64 num_positions = 3;
233: }
406: /* A metadata-only arithmetic sequence for unstable Lance 2.3 only.
407:  *
408:  * The value at index i is `start + step * i`. The container supplies the
409:  * number of values. Writers use this encoding only when step is positive and
410:  * the final value fits in the declared bit width.
411:  *
412:  * The input is a u32 or u64 fixed-width data block.
413:  * There is no output buffer.
414:  */
415: message Range {
416:   // The width of each decompressed value. Must be 32 or 64.
417:   uint64 uncompressed_bits_per_value = 1;
418:   // The first value in the sequence.
419:   uint64 start = 2;
420:   // The positive difference between adjacent values.
421:   uint64 step = 3;
422: }
423: 
424: /* An unstable Lance 2.3 non-decreasing unsigned fixed-width sequence
425:  * represented by its first value and the differences between adjacent values.
426:  *
427:  * The child contains one fewer value than the input. The container supplies
428:  * the input cardinality. Delta has a payload exactly when its child has one.
429:  *
430:  * The input is a u32 or u64 fixed-width data block.
431:  */
432: message Delta {
433:   // The width of each decompressed value. Must be 32 or 64.
434:   uint64 uncompressed_bits_per_value = 1;
435:   // The first uncompressed value.
436:   uint64 base = 2;
437:   // Compression applied to the adjacent differences.
438:   CompressiveEncoding deltas = 3;
439: }
653:         FixedSizeList fixed_size_list = 11;
654:         PackedStruct packed_struct = 12;
655:         VariablePackedStruct variable_packed_struct = 13;
656:         Range range = 14;
657:         Delta delta = 15;
658:     }
659: }
